/**
 * ⚠️ Өсөлт/бууралтыг ХУВИААР харуулна — зөвхөн тоо нь утгагүй.
 */
const b = $input.item.json.body;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => Number(n ?? 0).toLocaleString('mn-MN') + '₮';

const total = Number(b.totalRevenue ?? 0);
const prev = Number(b.prevRevenue ?? 0);

/* ⚠️ 0-д хуваахгүй — өчигдөр орлогогүй бол хувь тооцох утгагүй */
let trend = '';
if (prev > 0) {
  const pct = Math.round(((total - prev) / prev) * 100);
  trend = ' (' + (pct >= 0 ? '+' : '') + pct + '%)';
} else if (total > 0) {
  trend = ' (шинэ)';
}

const lines = ['<b>📊 BestTV — ' + esc(b.date) + '</b>', ''];
lines.push('💰 Орлого: <b>' + money(total) + '</b>' + trend);
if (b.planRevenue) lines.push('   ├ Багц: ' + money(b.planRevenue) + ' (' + b.planCount + ')');
if (b.rentalRevenue) lines.push('   ├ Түрээс: ' + money(b.rentalRevenue) + ' (' + b.rentalCount + ')');
if (b.topupRevenue) lines.push('   └ Цэнэглэлт: ' + money(b.topupRevenue));
lines.push('');
lines.push('👤 Шинэ хэрэглэгч: ' + (b.newUserCount ?? 0));
lines.push('👁 Үзэлт: ' + (b.viewCount ?? 0) + ' · Идэвхтэй: ' + (b.activeUserCount ?? 0));

if (b.topPlan) lines.push('\n🏆 Топ багц: ' + esc(b.topPlan.name) + ' (' + b.topPlan.count + ')');
if (b.topTitle) lines.push('🎬 Топ кино: ' + esc(b.topTitle.name) + ' (' + b.topTitle.views + ')');

/* ⚠️ Хүлээгдэж буй дансны төлбөр — ҮЙЛДЭЛ шаардсан тул тодруулна */
if (b.pendingBankCount > 0) {
  lines.push('\n⏳ <b>Шалгах дансны төлбөр: ' + b.pendingBankCount + '</b>');
}

return [{ json: { message: lines.join('\n') } }];
